{"path":"/root/solve.py","content":"#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

CATALOG_PATH = ROOT / 'therapy_catalog.json'
BAG_COST_PATH = ROOT / 'bag_supply_cost.csv'
DELIVERY_PAYMENT_PATH = ROOT / 'delivery_payment.csv'
PATIENT_OVERRIDES_PATH = ROOT / 'patient_overrides.csv'
ANALYSIS_PATH = ROOT / 'infusion_batch_analysis.json'
SUMMARY_PATH = ROOT / 'infusion_batch_summary.md'

SEVEN_DAY = {'days_per_delivery': 7, 'deliveries_per_year': 52}
FOURTEEN_DAY = {'days_per_delivery': 14, 'deliveries_per_year': 26}


def read_csv(path):
    with path.open(newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(float(value), 2)


def compute_financials(therapy, active_patients, bag_supply_cost, payment, model):
    days_per_delivery = model['days_per_delivery']
    deliveries_per_year = model['deliveries_per_year']
    annual_drug_cost = (
        float(therapy['drug_cost_per_1000_mg_usd'])
        * active_patients
        * float(therapy['dose_mg_per_day'])
        * days_per_delivery
        * deliveries_per_year
        / 1000
    )
    annual_supply_cost = bag_supply_cost * active_patients * deliveries_per_year
    annual_revenue = payment * active_patients * deliveries_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
    return {
        'days_per_delivery': days_per_delivery,
        'deliveries_per_year': deliveries_per_year,
        'annual_drug_cost_usd': money(annual_drug_cost),
        'annual_supply_cost_usd': money(annual_supply_cost),
        'annual_revenue_usd': money(annual_revenue),
        'annual_margin_usd': money(annual_margin),
    }


def main():
    with CATALOG_PATH.open() as f:
        catalog = json.load(f)

    bag_cost_rows = read_csv(BAG_COST_PATH)
    delivery_rows = read_csv(DELIVERY_PAYMENT_PATH)
    patient_rows = read_csv(PATIENT_OVERRIDES_PATH)

    in_scope = []
    lookup = {}
    by_code = {}
    for service_line in catalog.get('service_lines', []):
        for therapy in service_line.get('therapies', []):
            if therapy.get('include_in_review') is True:
                in_scope.append(therapy)
                by_code[therapy['therapy_code']] = therapy
                lookup[therapy['therapy_name']] = therapy
                for alias in therapy.get('aliases', []):
                    lookup[alias] = therapy

    bag_cost_by_size = {
        int(row['bag_size_ml']): float(row['bag_supply_cost_usd'])
        for row in bag_cost_rows
    }

    payment_by_code = {}
    for row in delivery_rows:
        therapy = lookup.get(row['therapy_label'])
        if therapy is None:
            continue
        payment_by_code[therapy['therapy_code']] = float(row['payment_per_delivery_per_patient_usd'])

    latest_approved_by_code = {}
    for row in patient_rows:
        if row.get('status') != 'approved':
            continue
        code = row.get('therapy_code')
        if code not in by_code:
            continue
        revision = int(row['revision'])
        current = latest_approved_by_code.get(code)
        if current is None or revision > int(current['revision']):
            latest_approved_by_code[code] = row

    therapies_out = []
    for therapy in in_scope:
        code = therapy['therapy_code']
        if code not in latest_approved_by_code:
            raise ValueError(f'Missing approved patient override for in-scope therapy {code}')
        if code not in payment_by_code:
            raise ValueError(f'Missing delivery payment for in-scope therapy {code}')

        patient_row = latest_approved_by_code[code]
        if 'patient_count' in patient_row and patient_row['patient_count'] != '':
            active_patients = int(patient_row['patient_count'])
        else:
            active_patients = int(patient_row['active_patients'])

        bag_size_ml = int(therapy['bag_size_ml'])
        bag_supply_cost = bag_cost_by_size[bag_size_ml]
        payment = payment_by_code[code]

        seven = compute_financials(therapy, active_patients, bag_supply_cost, payment, SEVEN_DAY)
        fourteen = compute_financials(therapy, active_patients, bag_supply_cost, payment, FOURTEEN_DAY)
        diff = money(fourteen['annual_margin_usd'] - seven['annual_margin_usd'])

        therapies_out.append({
            'therapy_code': code,
            'therapy_name': therapy['therapy_name'],
            'active_patients': active_patients,
            'bag_size_ml': bag_size_ml,
            'bag_supply_cost_usd': money(bag_supply_cost),
            'payment_per_delivery_per_patient_usd': money(payment),
            'drug_cost_per_1000_mg_usd': money(therapy['drug_cost_per_1000_mg_usd']),
            'dose_mg_per_day': money(therapy['dose_mg_per_day']),
            'financials_7_day': seven,
            'financials_14_day': fourteen,
            'annual_margin_difference_14_minus_7_usd': diff,
        })

    therapies_out.sort(key=lambda item: item['therapy_code'])

    total_7 = money(sum(t['financials_7_day']['annual_margin_usd'] for t in therapies_out))
    total_14 = money(sum(t['financials_14_day']['annual_margin_usd'] for t in therapies_out))
    total_diff = money(sum(t['annual_margin_difference_14_minus_7_usd'] for t in therapies_out))
    abs_diff = money(abs(total_diff))
    decision = 'move_to_14_day' if abs_diff < 15000 else 'keep_7_day'

    analysis = {
        'assumptions': {
            '7_day_model': SEVEN_DAY,
            '14_day_model': FOURTEEN_DAY,
            'currency': 'USD',
            'supply_cost_basis': 'one bag per delivery per patient',
            'decision_threshold_absolute_total_margin_difference_usd': 15000.00,
        },
        'therapies': therapies_out,
        'totals': {
            'total_annual_margin_7_day_usd': total_7,
            'total_annual_margin_14_day_usd': total_14,
            'total_annual_margin_difference_14_minus_7_usd': total_diff,
            'absolute_total_margin_difference_usd': abs_diff,
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f'Absolute total margin difference is ${abs_diff:,.2f}, '
                f"which is {'below' if abs_diff < 15000 else 'at or above'} the $15,000 threshold."
            ),
        },
    }

    with ANALYSIS_PATH.open('w') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    summary_lines = [
        f'Total 7-day margin (USD): {total_7:.2f}',
        f'Total 14-day margin (USD): {total_14:.2f}',
        f'Absolute difference (USD): {abs_diff:.2f}',
        f'Final decision: {decision}',
        analysis['recommendation']['justification'],
    ]
    SUMMARY_PATH.write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
